<script setup>
import {ref} from 'vue';import {useRouter,useRoute} from 'vue-router';import {useAuthStore} from '../stores/auth'
const username=ref(''),password=ref(''),message=ref(''),auth=useAuthStore(),router=useRouter(),route=useRoute()
async function submit(){message.value='';try{await auth.signIn(username.value,password.value);router.push(String(route.query.redirect||'/admin'))}catch(e){message.value=e.message}}
</script>
<template><section class="login"><div class="card surface"><div><RouterLink class="brand" to="/">Curly</RouterLink><span class="eyebrow">Account</span><h1>欢迎回来。</h1><p>登录后可进入管理后台。真正的管理员权限仍由 Go 后端校验。</p></div><form @submit.prevent="submit"><label>用户名<input v-model.trim="username" autocomplete="username" required></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required></label><button class="primary-button pressable" :disabled="auth.loading">{{auth.loading?'正在登录…':'登录'}}</button><p class="error" v-if="message">{{message}}</p></form></div></section></template>
<style scoped>.login{min-height:calc(100svh - var(--nav-height));padding:65px 20px;display:grid;place-items:center}.card{width:min(100%,880px);padding:clamp(28px,6vw,62px);border-radius:30px;display:grid;grid-template-columns:1fr 1fr;gap:55px}.brand{display:block;text-decoration:none;font-weight:800;margin-bottom:55px}h1{font-size:clamp(2.5rem,6vw,4.5rem);letter-spacing:-.055em;line-height:.98;margin:14px 0}.card p{color:var(--text-2);line-height:1.7}form{display:grid;gap:15px;align-content:center}label{display:grid;gap:7px;color:var(--text-2);font-size:.9rem}input{min-height:49px;border:1px solid var(--border);border-radius:14px;background:var(--surface-soft);color:var(--text-1);padding:0 13px}.error{color:var(--danger)!important}@media(max-width:760px){.card{grid-template-columns:1fr}.brand{margin-bottom:30px}}</style>
